export const ALL_SKILLS: SkillItem[] = [];

RAW_CATS.forEach((g) => {
  g[2].forEach((k) => {
    const slug = k[1];
    const ic = slug ? ICONS[slug] : null;
    let fillColor: string | undefined = undefined;
    if (ic) {
      const isCustom = k[2] && k[2].length === 6 && k[2] !== 'ffffff';
      if (isCustom) {
        fillColor = '#' + k[2];
      } else if (k[2] === 'ffffff' || lum(ic.h) < 0.24) {
        fillColor = 'currentColor';
      } else {
        fillColor = '#' + ic.h;
      }
    }
    ALL_SKILLS.push({
      name: k[0],
      slug: slug || undefined,
      abbr: !slug ? (k[2] || k[0].slice(0, 2).toUpperCase()) : undefined,
      group: g[0],
      color: g[1],
      path: ic ? ic.p : undefined,
      fillColor,
    });
  });
});

function lum(h: string) {
  if (!h || h.length < 6) return 0;
  const r = parseInt(h.substr(0, 2), 16);
  const g = parseInt(h.substr(2, 2), 16);
  const b = parseInt(h.substr(4, 2), 16);
  return (0.299 * r + 0.587 * g + 0.114 * b) / 255;
}
